content.css:
.circle {
  position: relative;
  box-sizing: border-box;
  border: 1px solid #1c87c9;
  border-radius: 50%;
  fill: #1c87c9;
}
p {
  text-align: center;
  line-height: 30px;
  font-size: 20px;
  font-weight: bold;
  position: relative;
  top: -30px;
  margin: 50% 0 0 0;
}
.errorMessage {
  text-align: center;
  font-size: 20px;
  overflow: hidden;
  text-overflow: ellipsis;
  top: 45%;
  width: 100%;
  position: absolute;
}
.clearCatcher {
  fill: transparent;
}
.legendItem {
  font-family: "Segoe UI";
}
.legendTitle {
  font-family: "Segoe UI Semibold", wf_segoe-ui_semibold, helvetica, arial, sans-serif;
}
.vennDiagram {
  cursor: default;
}
.legend {
  cursor: default;
}
.vennDiagram text {
  display: block;
  white-space: nowrap;
  text-anchor: middle;
}
